#include "../source/checkpoint_io.hpp"
#include <iostream>
using namespace prodck;
template<class F>void reject(F f){bool yes=false;try{f();}catch(const std::exception&){yes=true;}if(!yes)throw std::runtime_error("negative checkpoint fixture accepted");}
int main(int argc,char**argv){fs::path dir(argv[1]);fs::create_directories(dir);Header h;std::memset(h.identity,'a',64);h.mode=4;h.N_half=32;h.n_chunk=3ULL<<29;h.slab=1ULL<<25;h.next=h.slab;h.nslabs=1;std::vector<double>v(64,123.25);auto p=dir/"fixture.ck";write(p,h,v.data(),v.size()*8);auto r=read(p,h);if(r.payload.size()!=v.size()*8||std::memcmp(r.payload.data(),v.data(),v.size()*8))return 2;auto wrong=h;wrong.G=2;reject([&]{read(p,wrong);});wrong=h;wrong.next++;reject([&]{progress(wrong);});wrong=h;wrong.next=wrong.n_chunk;wrong.nslabs=10000;reject([&]{progress(wrong);});wrong=h;wrong.slab=32769;reject([&]{progress(wrong);});{std::ofstream f(p,std::ios::binary|std::ios::app);f.put('x');}reject([&]{read(p,h);});write(p,h,v.data(),v.size()*8);{std::fstream f(p,std::ios::binary|std::ios::in|std::ios::out);f.seekp(sizeof(h)+7);f.put('z');}reject([&]{read(p,h);});h.mode=0;h.next=h.n_chunk;h.nslabs=h.n_chunk/h.slab;v.resize(32);write(p,h,v.data(),v.size()*8);read(p,h);fs::remove_all(dir);std::cout<<"8 checkpoint roundtrip/identity/corruption/progress fixtures PASS\n";}
